syntax:
for (int i = 1; i <= n; i++) {          // outer loop: one round per ROW
    for (int s = 1; s <= n - i; s++) {  // inner loop 1: the spaces of this row
        cout << " ";
    }
    for (int j = 1; j <= 2 * i - 1; j++) {  // inner loop 2: the stars of this row
        cout << "*";
    }
    cout << endl;                        // end of the row: go to the next line
}

sample.code:
#include <iostream>
using namespace std;

int main() {
    int n = 3;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            cout << "*";
        }
        cout << endl;
    }
    return 0;
}

